import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2020-03-24 :: Ceph Crimson Meeting","description":"","frontmatter":{"title":"2020-03-24 :: Ceph Crimson Meeting","date":"2020-03-24T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","内存泄漏","B+树","数据压缩","项目管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-03-24_-_-_Ceph_Crimson_Meeting.md","filePath":"posts/2020/2020-03-24_-_-_Ceph_Crimson_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020-03-24_-_-_Ceph_Crimson_Meeting.md"};function r(n,l,s,p,u,h){return e(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次Ceph Crimson会议主要讨论了Ceph分布式存储系统的多个技术问题，包括内存泄漏、B+树设计、数据压缩算法以及项目管理工具的迁移等。团队成员分享了各自的工作进展，讨论了遇到的问题，并制定了后续的行动计划。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>内存泄漏问题</strong>：</p><ul><li>讨论了由社区关闭时未正确释放资源导致的内存泄漏问题。</li><li>决定进一步记录和分析泄漏原因，并寻找解决方案。</li></ul></li><li><p><strong>B+树设计</strong>：</p><ul><li>讨论了B+树的实现细节，特别是如何处理变长键和优化存储结构。</li><li>提出了使用固定部分和可变部分来优化键的存储，以减少空间浪费和提高查询效率。</li></ul></li><li><p><strong>数据压缩算法</strong>：</p><ul><li>讨论了使用Arcade压缩算法和共享前缀提取来优化数据存储。</li><li>决定进一步研究和实现这些算法，以提高数据存储效率。</li></ul></li><li><p><strong>项目管理工具迁移</strong>：</p><ul><li>讨论了从GitHub迁移到Trello进行项目管理的可行性和必要性。</li><li>决定进一步评估迁移的成本和收益，并与团队成员讨论以达成共识。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ol><li><p><strong>内存泄漏问题</strong>：</p><ul><li>继续跟踪和记录内存泄漏的具体情况，以便更好地理解和解决问题。</li></ul></li><li><p><strong>B+树设计</strong>：</p><ul><li>继续研究和优化B+树的存储结构，特别是键的处理方式。</li><li>考虑在内存中创建原型，以便更好地理解和测试B+树的操作。</li></ul></li><li><p><strong>数据压缩算法</strong>：</p><ul><li>进一步研究和实现Arcade压缩算法和共享前缀提取，以优化数据存储。</li></ul></li><li><p><strong>项目管理工具迁移</strong>：</p><ul><li>评估从GitHub迁移到Trello的成本和收益，并与团队成员讨论以决定是否迁移。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><p><strong>内存泄漏问题</strong>：</p><ul><li>分配专人负责跟踪和解决内存泄漏问题。</li><li>定期更新团队成员关于内存泄漏问题的进展。</li></ul></li><li><p><strong>B+树设计</strong>：</p><ul><li>分配专人负责B+树的设计和实现。</li><li>定期进行代码审查和测试，以确保B+树的稳定性和性能。</li></ul></li><li><p><strong>数据压缩算法</strong>：</p><ul><li>分配专人负责研究和实现数据压缩算法。</li><li>定期更新团队成员关于数据压缩算法的进展。</li></ul></li><li><p><strong>项目管理工具迁移</strong>：</p><ul><li>分配专人负责评估和准备项目管理工具的迁移。</li><li>定期与团队成员讨论迁移的进展和计划。</li></ul></li></ol><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>团队成员分享了各自的工作环境和当前的疫情情况，强调了在家工作的新常态。</li><li>讨论了如何更好地利用远程工作的时间，提高工作效率。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在团队成员的积极讨论和明确后续行动计划后结束，大家期待下一次会议的进展和成果。</p>',13)])])}const g=i(o,[["render",r]]);export{d as __pageData,g as default};
